CREATE TABLE IF NOT EXISTS "service_types" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(255) NOT NULL,
  "description" text,
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS "services" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "service_type_id" int NOT NULL,
  "name" varchar(255) NOT NULL,
  "description" text,
  "base_price" decimal(12,2) NOT NULL DEFAULT 0,
  "status" varchar(30) NOT NULL DEFAULT 'ACTIVE',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_services_service_type FOREIGN KEY ("service_type_id") REFERENCES "service_types" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_services_base_price CHECK (base_price > 0),
  CONSTRAINT chk_services_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

CREATE INDEX IF NOT EXISTS idx_services_status ON "services" ("status");
CREATE INDEX IF NOT EXISTS idx_services_service_type_id ON "services" ("service_type_id");
CREATE INDEX IF NOT EXISTS idx_services_id_status ON "services" ("id", "status");

